Object.assign(window.I18N.de, { caseMagazine:{
  crumb:"Projekte / Persönliches Projekt", title:"Mehrsprachiges Editorial-Portfolio", subtitle:"Ein professionelles Portfolio für meine Praktikumssuche 2027 und die BTS-SIO-SLAM-Prüfung, das eine redaktionelle Identität mit klaren technischen Nachweisen verbindet.", status:"In aktiver Entwicklung",
  galleryButton:"Aktuelle Ansichten ansehen", backProjects:"Zurück zu den Projekten", coverAlt:"Aktuelle Startseite des mehrsprachigen Editorial-Portfolios",
  typeLabel:"Projektart", type:"Professionelle Portfolio-Website", audienceLabel:"Zielgruppe", audience:"Personalverantwortliche · BTS-Prüfung", languagesLabel:"Sprachen", formatLabel:"Format", format:"Responsive Web · Desktop bis Mobilgerät",
  overviewEyebrow:"01 — Kontext & Ziel", overviewTitle:"Einen Werdegang als zusammenhängende redaktionelle Geschichte erzählen", overviewLead:"Das Portfolio unterstützt sowohl meine Praktikumssuche als auch die Präsentation meiner BTS-SIO-SLAM-Arbeiten.", overviewText:"Die Website vereint Profil, Berufserfahrung, Projekte, Technologiebeobachtung und Kontaktinformationen, ohne an Übersichtlichkeit zu verlieren. Das visuelle System nutzt Marineblau, Elfenbein und Gold, große redaktionelle Überschriften und klar strukturierte Inhaltsblöcke. Englisch bleibt die Standardsprache; Französisch und Deutsch sind vollständig verfügbar.", disclaimer:"Das Projekt entwickelt sich weiter. Die Bilder auf dieser Seite sind datierte Aufnahmen des aktuellen Stands und werden ersetzt, sobald Gestaltung und Inhalte abgeschlossen sind.",
  designEyebrow:"02 — Redaktionelle Richtung", designTitle:"Vier Prinzipien für die Oberfläche", designOneTitle:"Magazinidentität", designOneText:"Ausdrucksstarke Typografie, großzügige Kompositionen und nummerierte Abschnitte schaffen einen professionellen Rhythmus.", designTwoTitle:"Klare Hierarchie", designTwoText:"Informationen für Bewerbungen, BTS-Nachweise und Projektdetails bleiben auch auf umfangreichen Seiten erkennbar.", designThreeTitle:"Einheitliche Navigation", designThreeText:"Gemeinsame Kopf- und Fußzeilen, Sprachauswahl und wiederverwendbare Komponenten verbinden alle Bereiche.", designFourTitle:"Gezielter Farbeinsatz", designFourText:"Marineblau vermittelt Seriosität, Elfenbein verbessert die Lesbarkeit und Gold markiert Aktionen und Details.",
  techEyebrow:"03 — Technische Umsetzung", techTitle:"Eine schlanke Website ohne Framework", techTool:"Technologie", techUse:"Umsetzung", techResult:"Ergebnis", htmlUse:"Semantische Seitenstruktur, zugängliche Überschriften, Navigation, Abbildungen, Tabellen und Formulare.", htmlResult:"Verständliche und gut pflegbare Inhalte.", cssUse:"Gemeinsame Variablen, Grids, responsive Breakpoints, Fokuszustände und wiederverwendbare redaktionelle Komponenten.", cssResult:"Eine einheitliche Identität auf Desktop, Tablet und Mobilgerät.", jsUse:"Dynamische Projektkarten, Filter, Sprachwechsel, Metadaten und gemeinsame Navigationselemente.", jsResult:"Wiederverwendbares Verhalten ohne externes Framework.", formUse:"Sichere Weiterleitung des Kontaktformulars an die konfigurierte E-Mail-Adresse.", formResult:"Ein funktionsfähiger Kontaktkanal mit verständlicher Rückmeldung.",
  galleryEyebrow:"04 — Galerie der aktuellen Oberfläche", galleryTitle:"Eine Momentaufnahme des heutigen Portfolios", galleryIntro:"Diese vorläufigen Screenshots dokumentieren den aktuellen Projektstand. Sie werden erneuert, sobald Gestaltung und Inhalte ihre endgültige Form erreicht haben.", homeTitle:"Startseite", homeText:"Ein zweigeteilter redaktioneller Hero zeigt Praktikumsziel, Profil und wichtigste Handlungsoptionen.", homeAlt:"Aktuelle Startseite mit Porträt und Informationen zur Praktikumssuche", profileTitle:"Profil im Lebenslaufstil", profileText:"Ausbildung, Berufserfahrung, Sprachen und Downloads sind als übersichtlicher Online-Lebenslauf organisiert.", profileAlt:"Aktuelle Profilseite im Lebenslaufstil mit Ausbildung und Erfahrung", projectsTitle:"Projektübersicht", projectsText:"Filterbare Karten geben jedem schulischen, beruflichen oder persönlichen Projekt einen klaren Platz.", projectsAlt:"Aktuelle Projektseite mit Filtern und Fallstudienkarten", watchTitle:"Technologiebeobachtung", watchText:"Eine strukturierte BTS-SIO-Beobachtung verfolgt generative KI in der Softwareentwicklung anhand von Quellen und eigener Analyse.", watchAlt:"Aktuelle Technologiebeobachtungsseite zu generativer KI und Softwareentwicklung",
  qualityEyebrow:"05 — Qualitätsanforderungen", qualityTitle:"Mehr als eine visuelle Neugestaltung", qualityOneTitle:"Mehrsprachige Inhalte", qualityOneText:"Alle wichtigen Oberflächen und Texte stehen über eine zentrale Übersetzungsdatei auf Englisch, Französisch und Deutsch bereit.", qualityTwoTitle:"Responsive & zugänglich", qualityTwoText:"Layouts passen sich kleinen Bildschirmen an, der Tastaturfokus bleibt sichtbar und semantische Elemente unterstützen die Navigation.", qualityThreeTitle:"Pflegbare Struktur", qualityThreeText:"Gemeinsame Stile, datengesteuerte Projekte und wiederverwendbare Seitenelemente erleichtern sichere Aktualisierungen.",
  reflectionEyebrow:"06 — Persönliche Reflexion", reflectionTitle:"Was ich aus diesem Projekt lerne", reflectionLead:"Beim Aufbau meines eigenen Portfolios treffe ich technische Entscheidungen und denke gleichzeitig aus Sicht der zukünftigen Nutzer.", reflectionText:"Das Projekt stärkt meine Fähigkeit, eine wachsende Codebasis zu organisieren, konsistente Komponenten zu pflegen und für unterschiedliche Zielgruppen zu schreiben. Es zeigt mir außerdem, dass eine professionelle Website nicht nur visuell ist: Informationsqualität, Barrierefreiheit, responsives Verhalten und regelmäßige Prüfungen sind ebenso wichtig.",
  statusEyebrow:"Projektstatus", statusTitle:"Ein lebendiges Portfolio", statusText:"Die Hauptstruktur und die zentralen Seiten funktionieren, doch Projekte, Nachweise und Bilder werden sich während meines BTS SIO und der Praktikumssuche weiterentwickeln.", next:"Nächstes Projekt — Zeichenanwendung"
}});

